/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
/* Light is the default. Dark follows prefers-color-scheme and can be forced with <html data-theme="dark|light">. */
:root {
  color-scheme: light dark;
  /* color */
  --eq-color-background: #ffffff;
  --eq-color-surface: #f6f6f6;
  --eq-color-raised: #fafafa;
  --eq-color-text: #000000;
  --eq-color-muted-text: #616161;
  --eq-color-primary: #0000cc;
  --eq-color-on-primary: #ffffff;
  --eq-color-secondary: #ffdd00;
  --eq-color-accent: #b00020;
  --eq-color-border: #c7c7c7;
  --eq-color-border-strong: #737373;
  --eq-color-ring: #0000cc;
  --eq-color-destructive: #c62828;
  --eq-color-success: #1b7a43;
  --eq-color-warning: #8f5b00;

  /* font */
  --eq-font-family-sans: 'Atkinson Hyperlegible', Pretendard, 'Noto Sans KR', sans-serif;
  --eq-font-family-mono: 'JetBrains Mono', ui-monospace, monospace;
  --eq-font-weight-regular: 400;
  --eq-font-weight-bold: 700;

  /* space */
  --eq-space-1: 4px;
  --eq-space-2: 8px;
  --eq-space-3: 16px;
  --eq-space-4: 24px;
  --eq-space-5: 32px;
  --eq-space-6: 48px;
  --eq-space-7: 64px;
  --eq-space-8: 96px;

  /* radius */
  --eq-radius-sm: 2px;
  --eq-radius-md: 4px;
  --eq-radius-lg: 6px;
  --eq-radius-full: 9999px;

  /* motion */
  --eq-duration-fast: 0ms;
  --eq-duration-base: 80ms;
  --eq-duration-slow: 120ms;

  /* motion */
  --eq-easing-standard: cubic-bezier(0, 0, 1, 1);

  /* type roles: weight size/line-height family */
  --eq-type-display: 700 55px/1.25 var(--eq-font-family-sans);
  --eq-type-display-tracking: 0em;
  --eq-type-h1: 700 44px/1.25 var(--eq-font-family-sans);
  --eq-type-h1-tracking: 0em;
  --eq-type-h2: 700 35px/1.25 var(--eq-font-family-sans);
  --eq-type-h2-tracking: 0em;
  --eq-type-h3: 700 28px/1.25 var(--eq-font-family-sans);
  --eq-type-h3-tracking: 0em;
  --eq-type-body: 400 18px/1.6 var(--eq-font-family-sans);
  --eq-type-body-tracking: 0em;
  --eq-type-small: 400 14px/1.6 var(--eq-font-family-sans);
  --eq-type-small-tracking: 0em;
  --eq-type-mono: 400 14px/1.6 var(--eq-font-family-mono);
  --eq-type-mono-tracking: 0em;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --eq-color-background: #000000;
    --eq-color-surface: #0d0d0d;
    --eq-color-raised: #1a1a1a;
    --eq-color-text: #ffffff;
    --eq-color-muted-text: #9e9e9e;
    --eq-color-primary: #ffdd00;
    --eq-color-on-primary: #000000;
    --eq-color-secondary: #222222;
    --eq-color-accent: #66ccff;
    --eq-color-border: #383838;
    --eq-color-border-strong: #8c8c8c;
    --eq-color-ring: #ffdd00;
    --eq-color-destructive: #ff7b72;
    --eq-color-success: #4cc38a;
    --eq-color-warning: #e8b44a;
  }
}
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] {
  color-scheme: dark;
  --eq-color-background: #000000;
  --eq-color-surface: #0d0d0d;
  --eq-color-raised: #1a1a1a;
  --eq-color-text: #ffffff;
  --eq-color-muted-text: #9e9e9e;
  --eq-color-primary: #ffdd00;
  --eq-color-on-primary: #000000;
  --eq-color-secondary: #222222;
  --eq-color-accent: #66ccff;
  --eq-color-border: #383838;
  --eq-color-border-strong: #8c8c8c;
  --eq-color-ring: #ffdd00;
  --eq-color-destructive: #ff7b72;
  --eq-color-success: #4cc38a;
  --eq-color-warning: #e8b44a;
}
